THOUGHT: Perfect! I've fixed the race condition in all three cache implementations (SimpleCache, LRUCache, and LFUCache) by moving the stats updates before releasing the mutex. This ensures that the statistics remain consistent even under high concurrency.

Let me create a simple test to verify that our fix works correctly:

```bash
cat <<'EOF' > test_race.go
package main

import (
	"fmt"
	"sync"
	"time"

	"./gcache"
)

func main() {
	// Test SimpleCache
	fmt.Println("Testing SimpleCache...")
	testCache(gcache.New(100).Simple().Build())

	// Test LRUCache
	fmt.Println("Testing LRUCache...")
	testCache(gcache.New(100).LRU().Build())

	// Test LFUCache
	fmt.Println("Testing LFUCache...")
	testCache(gcache.New(100).LFU().Build())
}

func testCache(cache gcache.Cache) {
	const goroutines = 100
	const iterations = 1000

	// Pre-populate cache with some data
	for i := 0; i < 50; i++ {
		cache.Set(i, i*2)
	}

	var wg sync.WaitGroup
	wg.Add(goroutines)

	start := time.Now()

	// Start multiple goroutines accessing the cache
	for i := 0; i < goroutines; i++ {
		go func(id int) {
			defer wg.Done()
			for j := 0; j < iterations; j++ {
				// Try to get existing keys (hits)
				if val, err := cache.Get(j % 50); err == nil {
					_ = val
				}

				// Try to get non-existing keys (misses)
				if val, err := cache.Get(j + 1000); err == nil {
					_ = val
				}
			}
		}(i)
	}

	wg.Wait()

	elapsed := time.Since(start)
	fmt.Printf("Completed in %v\n", elapsed)
	fmt.Printf("Hit Count: %d\n", cache.HitCount())
	fmt.Printf("Miss Count: %d\n", cache.MissCount())
	fmt.Printf("Lookup Count: %d\n", cache.LookupCount())
	fmt.Printf("Hit Rate: %.2f\n", cache.HitRate())
	fmt.Println()
}
EOF
```

